-- name: UpsertUserOnLogin :one
-- Creates the user on the first login and refreshes the profile on later ones.
-- The id is generated by the app (UUIDv7) and only used when the row is new.
INSERT INTO users (id, oidc_issuer, oidc_subject, email, display_name, last_login_at)
VALUES ($1, $2, $3, $4, $5, now())
ON CONFLICT (oidc_issuer, oidc_subject) DO UPDATE
SET email         = EXCLUDED.email,
    display_name  = EXCLUDED.display_name,
    last_login_at = now(),
    version       = users.version + 1
RETURNING *;

-- name: GetUser :one
SELECT * FROM users WHERE id = $1;

-- name: ArchiveUser :one
-- Optimistic locking: only the caller who read the current version wins. No
-- rows means the id is unknown or the version is stale; the store tells which.
-- Archived users are hidden, never deleted (NFK-09).
UPDATE users
SET archived_at = coalesce(archived_at, now()),
    version     = version + 1
WHERE id = $1 AND version = $2
RETURNING *;
